    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    margin: 0;
}

.container {
    background-color: var(--card-bg);
    padding: 2.5rem;
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
    width: 100%;
    max-width: 450px;
}

h1 {
    margin-top: 0;
    font-size: 1.8rem;
    color: var(--accent-color);
    text-align: center;
    margin-bottom: 2rem;
}

.form-field {
    margin-bottom: 1.5rem;
    display: flex;
    flex-direction: column;
}

label {
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: var(--text-secondary);
}

input {
    background-color: var(--input-bg);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 0.8rem;
    color: var(--text-primary);
    font-size: 1rem;
    transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
    outline: none;
    border-color: var(--accent-color);
    box-shadow: 0 0 0 2px rgba(187, 134, 252, 0.2);
}

input.error {
    border-color: var(--error-color);
}

.error-message {
    color: var(--error-color);
    font-size: 0.85rem;
    margin-top: 0.4rem;
    min-height: 1.2rem;
}

.helper-text {
    color: var(--text-secondary);
    font-size: 0.8rem;
    margin-top: 0.3rem;
    font-style: italic;
}

button {
    background-color: var(--accent-color);
    color: #000;
    border: none;
    border-radius: 6px;
    padding: 1rem;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    width: 100%;
    margin-top: 1rem;
    transition: background-color 0.2s, transform 0.1s;
}

button:hover {
    background-color: #a370f7;
}

button:active {
    transform: scale(0.98);
}

button:disabled {
    background-color: #444;
    color: #888;
    cursor: not-allowed;
}

.success-message {
    text-align: center;
    color: #4caf50;
    font-weight: bold;
}
    </style>
</head>
<body>
    <div id="root"></div>
    <script type="text/babel">
const { useState } = React;

const FormField = ({ label, name, type = "text", value, onChange, error, required, helperText }) => {
    return (
        <div className="form-field">
            <label htmlFor={name}>
                {label} {required && <span style={{ color: 'var(--error-color)' }}>*</span>}
            </label>
            <input
                id={name}
                name={name}
                type={type}
                value={value}
                onChange={onChange}
                className={error ? 'error' : ''}
                placeholder={label}
            />
            {helperText && <div className="helper-text">{helperText}</div>}
            {error && <div className="error-message">{error}</div>}
        </div>
    );
};

const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });
    const [errors, setErrors] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const validate = (name, value) => {
        let error = '';
        if (name === 'fullName') {
            if (!value.trim()) error = 'Full name is required';
        } else if (name === 'email') {
            if (!value.trim()) {
                error = 'Email is required';
            } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
                error = 'Invalid email format';
            }
        } else if (name === 'phone') {
            if (value && !/^\+?\d{1,4}?[-.\s]?\(?\d{1,3}?\)?[-.\s]?\d{1,4}[-.\s]?\d{1,4}[-.\s]?\d{1,9}$/.test(value)) {
                error = 'Invalid phone format';
            }
        }
        return error;
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));

        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const newErrors = {};
        Object.keys(formData).forEach(key => {
            const error = validate(key, formData[key]);
            if (error) newErrors[key] = error;
        });

        if (Object.keys(newErrors).length === 0) {
            console.log('Form submitted:', formData);
            setSubmitted(true);
        } else {
            setErrors(newErrors);
        }
    };

    if (submitted) {
        return (
            <div className="success-message">
                <h2>Thank you!</h2>
                <p>Your support request has been sent.</p>
                <button onClick={() => setSubmitted(false)}>Send another message</button>
            </div>
        );
    }

    return (
        <form onSubmit={handleSubmit} noValidate>
            <h1>Contact Support</h1>

            <FormField
                label="Full Name"
                name="fullName"
                value={formData.fullName}
                onChange={handleChange}
                error={errors.fullName}
                required
            />

            <FormField
                label="Email Address"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                error={errors.email}
                required
            />

            <FormField
                label="Phone Number"
                name="phone"
                type="tel"
                value={formData.phone}
                onChange={handleChange}
                error={errors.phone}
                helperText="Expected format: +1-234-567-8901"
            />

            <button type="submit">Submit Request</button>
        </form>
    );
};

const App = () => {
    return (
        <div className="container">
            <ContactForm />
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
    </script>
</body>
</html>
