    <div id="root"></div>
    <script type="text/babel">
const { useState } = React;

const FormField = ({ label, name, type = "text", value, onChange, error, required, helperText }) => {
    return (
        <div className="form-field">
            <label htmlFor={name}>
                {label} {required && <span style={{ color: 'var(--error-color)' }}>*</span>}
            </label>
            <input
                id={name}
                name={name}
                type={type}
                value={value}
                onChange={onChange}
                className={error ? 'error' : ''}
                placeholder={label}
            />
            {helperText && <div className="helper-text">{helperText}</div>}
            {error && <div className="error-message">{error}</div>}
        </div>
    );
};

const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });
    const [errors, setErrors] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const validate = (name, value) => {
        let error = '';
        if (name === 'fullName') {
            if (!value.trim()) error = 'Full name is required';
        } else if (name === 'email') {
            if (!value.trim()) {
                error = 'Email is required';
            } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
                error = 'Invalid email format';
            }
        } else if (name === 'phone') {
            if (value && !/^\+?\d{1,4}?[-.\s]?\(?\d{1,3}?\)?[-.\s]?\d{1,4}[-.\s]?\d{1,4}[-.\s]?\d{1,9}$/.test(value)) {
                error = 'Invalid phone format';
            }
        }
        return error;
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));

        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const newErrors = {};
        Object.keys(formData).forEach(key => {
            const error = validate(key, formData[key]);
            if (error) newErrors[key] = error;
        });

        if (Object.keys(newErrors).length === 0) {
            console.log('Form submitted:', formData);
            setSubmitted(true);
        } else {
            setErrors(newErrors);
        }
    };

    if (submitted) {
        return (
            <div className="success-message">
                <h2>Thank you!</h2>
                <p>Your support request has been sent.</p>
                <button onClick={() => setSubmitted(false)}>Send another message</button>
            </div>
        );
    }

    return (
        <form onSubmit={handleSubmit} noValidate>
            <h1>Contact Support</h1>

            <FormField
                label="Full Name"
                name="fullName"
                value={formData.fullName}
                onChange={handleChange}
                error={errors.fullName}
                required
            />

            <FormField
                label="Email Address"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                error={errors.email}
                required
            />

            <FormField
                label="Phone Number"
                name="phone"
                type="tel"
                value={formData.phone}
                onChange={handleChange}
                error={errors.phone}
                helperText="Expected format: +1-234-567-8901"
            />

            <button type="submit">Submit Request</button>
        </form>
    );
};

const App = () => {
    return (
        <div className="container">
            <ContactForm />
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
    </script>
</body>
</html>
